static int parse_one(const char *path, struct samp *out)
{
        FILE *fp;
        char line[128];
        int got_end = 0;

        memset(out, 0, sizeof(*out));
        fp = fopen(path, "r");
        if (!fp)
                return -1;
        while (fgets(line, sizeof(line), fp)) {
                char *nl = strpbrk(line, "\r\n");
                if (nl)
                        *nl = 0;
                if (strcmp(line, "END") == 0) {
                        got_end = 1;
                        break;
                } else if (strncmp(line, "SEQ ", 4) == 0) {
                        out->seq = (uint32_t)strtoul(line + 4, NULL, 10);
                } else if (strncmp(line, "HITS ", 5) == 0) {
                        out->hits = (uint32_t)strtoul(line + 5, NULL, 10);
                } else if (line[0]) {
                        if (out->depth >= MAX_FR) {
                                fclose(fp);
                                return -1;
                        }
                        strncpy(out->fr[out->depth], line, MAX_LN - 1);
                        out->fr[out->depth][MAX_LN - 1] = 0;
                        out->depth++;
                }
        }
        if (ferror(fp) || fclose(fp) != 0)
                return -1;
        return got_end ? 0 : -1;
}

static int samp_cmp(const void *va, const void *vb)
{
        const struct samp *a = va;
        const struct samp *b = vb;
        int i, n, c;

        n = a->depth < b->depth ? a->depth : b->depth;
        for (i = 0; i < n; i++) {
                c = strcmp(a->fr[i], b->fr[i]);
                if (c)
                        return c;
        }
        if (a->depth != b->depth)
                return a->depth < b->depth ? -1 : 1;
        if (a->seq != b->seq)
                return a->seq < b->seq ? -1 : 1;
        if (a->hits != b->hits)
                return a->hits < b->hits ? -1 : 1;
        return 0;
}

int cfg_walk(const char *a)
{
        DIR *d;
        struct dirent *de;

        ntab = 0;
        (void)g_join;
        d = opendir(a ? a : ".");
        if (!d)
