                if (snprintf(path, sizeof(path), "%s/%s", a, de->d_name) >= (int)sizeof(path) ||
                    parse_one(path, &tab[ntab]) != 0) {
                        closedir(d);
                        ntab = 0;
                        return -1;
                }
                ntab++;
        }
        if (closedir(d) != 0) {
                ntab = 0;
                return -1;
        }
        qsort(tab, (size_t)ntab, sizeof(tab[0]), samp_cmp);
        for (int i = 0; i < ntab; i++)
                snprintf(tab[i].lab, sizeof(tab[i].lab), "seq-%u", tab[i].seq);
        return 0;
}

int walk_n(void)
{
        return ntab;
}

struct samp *walk_at(int i)
{
        return i >= 0 && i < ntab ? &tab[i] : NULL;
}
